        return new List<Job>().AsQueryable();
    try
    {

        DateTime start = startI.ToUniversalTime();
        DateTime end = endI.ToUniversalTime();
        if (end.Hour != 0)
        {
            start = new DateTime(startI.Year, startI.Month, startI.Day, 0, 0, 0);
            end = new DateTime(endI.Year, endI.Month, endI.Day, 23, 59, 0);
        }
        if (myUser.IsSystemManager==true)
        {
            return (from job in _db.Context.Jobs.DefaultIfEmpty()
                    join task in _db.Context.Tasks on job.ParentId equals task.Id
                    where (job.start == null || (job.start <= end && job.end >= start)) && job.MainUserId==myUser.MainUserId && task.MainUserId==myUser.MainUserId
                    select job
                    );

        }
        if (myUser.IsClientManager==true)
        {
            string Client = myUser.Client;
            string[] Clients = Client.Split(',');
            List<Task> mytasks = _db.Context.Tasks.Where(e => Clients.Contains(e.Client)).ToList();
            return (from job in _db.Context.Jobs join task in _db.Context.Tasks on job.ParentId equals task.Id where Clients.Contains(task.Client) && job.start <= end && job.end >= start && job.MainUserId==myUser.MainUserId && task.MainUserId==myUser.MainUserId select job);


        }
        if (myUser.IsFilialManager==true)
        {
            string Filial = myUser.Filial;
            return (from job in _db.Context.Jobs join task in _db.Context.Tasks on job.ParentId equals task.Id where task.Filial == Filial && job.start <= end && job.end >= start && task.MainUserId==myUser.MainUserId && job.MainUserId==myUser.MainUserId select job);
        }
        else
        {
            string MemberId = myUser.Id.ToString();
            return (from job in _db.Context.Jobs join task in _db.Context.Tasks on job.ParentId equals task.Id where job.MemberId == MemberId && job.start <= end && job.end >= start && task.MainUserId == myUser.MainUserId && job.MainUserId == myUser.MainUserId select job);

        }
    }
    catch (Exception em)
    {
        return new List<Job>().AsQueryable();
